<script setup lang="ts">
import {appUrl} from '../lib/urls';
import {computed,ref} from 'vue';
import {Head,useForm,usePage} from '@inertiajs/vue3';
import {ArrowRight,Sparkles,ShieldCheck,LoaderCircle,Building2,ChevronLeft} from 'lucide-vue-next';
defineProps<{canRegister:boolean;suiteConfigured:boolean}>();
const register=ref(false);const suite=ref(false);const page=usePage();
const flashError=computed(()=>(page.props.flash as Record<string,any>|undefined)?.error);
const form=useForm({name:'',email:'',password:'',password_confirmation:'',remember:true});
function changeMode(useSuite:boolean){suite.value=useSuite;register.value=false;form.reset('password','password_confirmation');form.clearErrors();}
function submit(){form.post(appUrl(register.value?'/register':suite.value?'/auth/suite':'/login'),{onFinish:()=>form.reset('password','password_confirmation')});}
</script>
<template><Head title="Entrar"/><div class="auth-layout"><aside class="auth-story"><a class="brand" :href="appUrl('/')"><img class="brand-logo" :src="appUrl('/brand/g-analise-icon.png')" alt=""><span class="brand-wordmark"><span class="brand-product">G-Analise <span class="brand-ai">IA</span></span><small>UM PRODUTO INOVADORA</small></span></a><div><span class="welcome-eyebrow"><Sparkles :size="16"/> SEU PRÓXIMO DASHBOARD COMEÇA AQUI</span><h1>Boas perguntas.<br>Grandes decisões.</h1><p>Um espaço para transformar suas ideias em dashboards, com inteligência artificial e todo o poder do G-Analise BI.</p><div class="auth-visual"><div><span>RECEITA EM FOCO</span><strong>Uma nova perspectiva.</strong><div class="auth-bars"><i v-for="h in [30,45,37,62,55,74,66,83,73,96]" :key="h" :style="{height:h+'%'}"></i></div></div></div></div><footer><ShieldCheck :size="15"/> Seus acessos. Suas permissões. Seu controle.</footer></aside><main class="auth-form-panel"><div><span class="section-eyebrow">BEM-VINDO AO SEU WORKSPACE</span><h1>{{register?'Crie sua conta':suite?'Entre com a Suíte':'Vamos continuar?'}}</h1><p>{{register?'Prepare seu espaço para criar com inteligência.':suite?'Use seu e-mail e sua senha de colaborador da Inovadora.':'Entre para acessar seus projetos e conversas.'}}</p><button v-if="suiteConfigured&&!register&&!suite" class="provider-connect auth-suite" @click="changeMode(true)"><Building2 :size="20"/><span>Entrar com a Suíte<small>Colaboradores Inovadora</small></span><ArrowRight :size="16"/></button><button v-if="suite" class="auth-mode-back" @click="changeMode(false)"><ChevronLeft :size="15"/>Entrar com e-mail do G-Analise IA</button><div v-else-if="suiteConfigured" class="auth-divider">ou entre com seu e-mail</div><form @submit.prevent="submit"><label v-if="register">Nome<input v-model="form.name" required autocomplete="name"></label><label>{{suite?'E-mail da Suíte':'E-mail'}}<input v-model="form.email" type="email" required autocomplete="username" placeholder="voce@empresa.com.br"></label><label>{{suite?'Senha da Suíte':'Senha'}}<input v-model="form.password" type="password" required :autocomplete="register?'new-password':'current-password'" :minlength="register?12:undefined"></label><label v-if="register">Confirme a senha<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"></label><div v-if="flashError&&!Object.keys(form.errors).length" class="form-error" role="alert">{{flashError}}</div><div v-if="Object.keys(form.errors).length" class="form-error" role="alert">{{Object.values(form.errors)[0]}}</div><button class="primary-button full-width auth-submit" :disabled="form.processing"><LoaderCircle v-if="form.processing" :size="18" class="spin"/>{{register?'Criar conta':suite?'Entrar com a Suíte':'Entrar no workspace'}}<ArrowRight :size="17"/></button></form><p v-if="canRegister&&!suite" class="auth-register">{{register?'Já tem uma conta?':'Primeiro acesso?'}} <button @click="register=!register;suite=false;form.reset('password','password_confirmation');form.clearErrors()">{{register?'Entrar':'Criar conta'}}</button></p><p v-else class="auth-note">Seu acesso é disponibilizado pelo administrador da instalação.</p><small class="auth-privacy">G-Analise IA é um produto Inovadora integrado ao G-Analise BI.</small></div></main></div></template>

<style scoped>
.auth-suite{display:flex;width:100%;align-items:center;text-align:left;gap:12px;margin-top:16px;padding:14px 16px;background:#f1f6ff;border:1px solid #dae5f8;color:#4773b0;border-radius:8px}.auth-suite:hover{background:#e8f1ff;border-color:#accaf4}.auth-suite>span{flex:1;font-size:13px;font-weight:600}.auth-suite small{display:block;font-size:10px;font-weight:400;color:#8ba1be;margin-top:5px}.auth-mode-back{display:flex;align-items:center;gap:6px;font-size:11px;color:#8296b4;margin-top:22px}.auth-mode-back:hover{color:#2264c3}
</style>
